source_item ? 'historical_line_amount_evidence' THEN\n     RAISE EXCEPTION 'RESTORATION_SOURCE_EXTENSION_INVALID' USING ERRCODE='23514'; END IF;\n    FOREACH restoration_extension IN ARRAY ARRAY['explicit_zero_evidence','zero_amount_archive','historical_hall_evidence'] LOOP\n     IF (source_item ? restoration_extension) IS DISTINCT FROM (source_entry ? restoration_extension)\n      OR source_item->restoration_extension IS DISTINCT FROM source_entry->restoration_extension THEN\n      RAISE EXCEPTION 'RESTORATION_SOURCE_EXTENSION_DIFFERS' USING ERRCODE='23514'; END IF;\n     IF source_item ? restoration_extension THEN\n      IF jsonb_typeof(source_item->restoration_extension) IS DISTINCT FROM 'object'\n       OR (restoration_extension='explicit_zero_evidence' AND (proof_target.kind IS DISTINCT FROM 'INVENTORY_KEY' OR source_item->'fields'->>'quantity' IS DISTINCT FROM '0'))\n       OR (restoration_extension IN ('zero_amount_archive','historical_hall_evidence') AND proof_target.kind IS DISTINCT FROM 'SALES_HEADER') THEN\n       RAISE EXCEPTION 'RESTORATION_SOURCE_EXTENSION_INVALID' USING ERRCODE='23514'; END IF;\n      restoration_source_fields:=restoration_source_fields||jsonb_build_object(restoration_extension,source_item->restoration_extension);\n     END IF;\n    END LOOP;\n   END IF;\n   IF source_record.source_system IS DISTINCT FROM documents_batch.source_name OR source_record.reviewed_at IS NULL"},{"before":"source_item->>'source_hash' IS DISTINCT FROM encode(sha256(convert_to(jsonb_build_object('source_key',source_item->>'source_key','fields',source_item->'fields','source_refs',source_item->'source_refs')::text,'UTF8')),'hex')","after":"source_item->>'source_hash' IS DISTINCT FROM encode(sha256(convert_to(restoration_source_fields::text,'UTF8')),'hex')"}],"security_definer":false,"returns":"trigger"},{"signature":"naijue_erp.standard_whole_package_verify_v2(jsonb,text)","predecessor_sha256":"9701799d765bed4c8ab015dc513d60857a75f843b860aa9fef16c6ba87ab4dca","successor_sha256":"1dbd97f4dfabcbb47df4aac66bb9536098f7e5e539fa678fd888bc7090076d4b","replacements":[{"before":"DECLARE request jsonb; inspected jsonb;","after":"DECLARE amount_differences jsonb; request jsonb; inspected jsonb;"},{"before":" RETURN jsonb_build_object('protocol','STANDARD_IMPORT_SQL_V1','plan_sha256',request->>'plan_sha256','batch_id',documents_batch.id","after":" -- The existing credential-bound verifier already fences source and current\n -- rows and validates every origin and edit above. Return both without rewriting.\n SELECT coalesce(jsonb_agg(jsonb_build_object('sales_id',ln.sales_id,'line_id',ln.id,\n  'source_key',src.source_key,'source_namespace',src.source_system,'source_refs',p->'source_refs',\n  'original_quantity',p->'fields'->>'quantity','original_deal_price',p->'fields'->>'deal_price','original_line_amount',p->'fields'->>'line_amount',\n  'calculated_line_amount',((p->'fields'->>'quantity')::numeric*(p->'fields'->>'deal_price')::numeric)::text,\n  'difference',((p->'fields'->>'line_amount')::numeric-(p->'fields'->>'quantity')::numeric*(p->'fields'->>'deal_price')::numeric)::text,\n  'current_quantity',ln.quantity::text,'current_deal_price',ln.deal_price::text,'current_line_amount',ln.line_amount::text,\n  'current_matches_original',ln.quantity::text=(p->'fields'->>'quantity') AND ln.deal_price::text=(p->'fields'->>'deal_price') AND ln.line_amount::text=(p->'fields'->>'line_amount'),\n  'evidence',p->'historical_line_amount_evidence','disposition','PRESERVED_SOURCE_DIFFERENCE') ORDER BY ln.sales_id,ln.line_no,ln.id),'[]'::jsonb)\n INTO amount_differences FROM naijue_erp.import_record src CROSS JOIN LATERAL naijue_erp.standard_import_record_proof(src.id) p\n JOIN naijue_erp.sales_line ln ON ln.id=src.target_id JOIN naijue_erp.sales_header hh ON hh.id=ln.sales_id AND hh.import_batch_id=src.import_batch_id\n WHERE src.import_batch_id=documents_batch.id AND src.target_type='SALES_LINE' AND p ? 'historical_line_amount_evidence';\n RETURN jsonb_build_object('historical_line_amount_differences',amount_differences,'protocol','STANDARD_IMPORT_SQL_V1','plan_sha256',request->>'plan_sha256','batch_id',documents_batch.id"}],"security_definer":true,"returns":"jsonb"}]$amount_source_changes$::jsonb;
 spec jsonb; change jsonb; routine oid; before_body text; after_body text; definition text;
 before_meta jsonb; after_meta jsonb;
BEGIN
 IF (SELECT array_agg(c.relname::text ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='naijue_erp' AND c.relkind IN ('r','p')) IS DISTINCT FROM ARRAY['audit_change','auth_session','barcode_scheme','color','customer','fit','hall','import_batch','import_record','inventory_balance','inventory_ledger','operation_receipt','payment_account','payment_account_hall','payment_method','product','product_category','product_image','runtime_document_number_allocation','sales_header','sales_line','sales_settlement','schema_migration','season','size','size_group','size_group_member','sku','sku_barcode','staff','supplier','transfer_header','transfer_line','user_account','warehouse']::text[]
  OR (SELECT count(*) FROM pg_proc WHERE pronamespace='naijue_erp'::regnamespace AND prokind IN ('f','p'))<>152 THEN
  RAISE EXCEPTION 'HISTORICAL_LINE_AMOUNT_EXACT35_PREDECESSOR_REQUIRED' USING ERRCODE='55000'; END IF;
 FOR spec IN SELECT value FROM jsonb_array_elements(specs) LOOP
  routine:=to_regprocedure(spec->>'signature');
  SELECT p.prosrc,to_jsonb(p)-'prosrc' INTO before_body,before_meta FROM pg_proc p WHERE p.oid=routine;
  IF before_body IS NULL OR encode(sha256(convert_to(before_body,'UTF8')),'hex') IS DISTINCT FROM spec->>'predecessor_sha256' THEN
   RAISE EXCEPTION 'HISTORICAL_LINE_AMOUNT_PREDECESSOR_DIFFERS: %',spec->>'signature' USING ERRCODE='55000'; END IF;
  IF before_meta->'prosecdef' IS DISTINCT FROM spec->'security_definer'
   OR before_meta->>'prorettype' IS DISTINCT FROM (spec->>'returns')::regtype::oid::text
   OR before_meta->>'proowner' IS DISTINCT FROM (SELECT nspowner::text FROM pg_namespace WHERE nspname='naijue_erp')
   OR (before_meta->'proconfig' @> '["search_path=pg_catalog, naijue_erp, pg_temp"]'::jsonb) IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'HISTORICAL_LINE_AMOUNT_METADATA_UNSAFE' USING ERRCODE='55000'; END IF;
  definition:=pg_get_functiondef(routine);after_body:=before_body;
  FOR change IN SELECT value FROM jsonb_array_elements(spec->'replacements') LOOP
   IF coalesce(length(change->>'before'),0)=0
    OR (length(after_body)-length(replace(after_body,change->>'before','')))/length(change->>'before')<>1
    OR (length(definition)-length(replace(definition,change->>'before','')))/length(change->>'before')<>1 THEN
    RAISE EXCEPTION 'HISTORICAL_LINE_AMOUNT_ANCHOR_DIFFERS' USING ERRCODE='55000'; END IF;
   after_body:=replace(after_body,change->>'before',change->>'after');
   definition:=replace(definition,change->>'before',change->>'after');
  END LOOP;
  IF encode(sha256(convert_to(after_body,'UTF8')),'hex') IS DISTINCT FROM spec->>'successor_sha256' THEN
   RAISE EXCEPTION 'HISTORICAL_LINE_AMOUNT_OUTPUT_DIFFERS' USING ERRCODE='55000'; END IF;
  EXECUTE definition;
  SELECT p.prosrc,to_jsonb(p)-'prosrc' INTO after_body,after_meta FROM pg_proc p WHERE p.oid=routine;
  IF before_meta IS DISTINCT FROM after_meta OR encode(sha256(convert_to(after_body,'UTF8')),'hex') IS DISTINCT FROM spec->>'successor_sha256' THEN
   RAISE EXCEPTION 'HISTORICAL_LINE_AMOUNT_POSTCONDITION_FAILED' USING ERRCODE='55000'; END IF;
 END LOOP;
END $historical_line_amount$;
COMMIT;
